$files = Get-ChildItem -Path 'frontend\\src' -Recurse -Include *.jsx,*.js
foreach \($f in $files\) {
    $c = Get-Content $f.FullName -Raw
    if \($c -match 'urable\\.com'\) {
        $c = $c -creplace "https://app\\.urable\\.com/virtual-shop/SxuPVxIQ2P7KOV77y6qD[^'""]*", '/book-appointment'
        $c = $c -creplace "https://app\\.urable\\.com/virtual-shop/rB9FHJFIfifYgU8Ty9Yw[^'""]*", '/book-appointment'
        Set-Content -Path $f.FullName -Value $c -NoNewline
        Write-Host "Updated: $\($f.Name\)"
    }
}
PSEOF)

Bash("c:\\Users\\austi\\Desktop\\supremedetailstudio\\remove-target-blank.ps1" << 'PSEOF'
$files = Get-ChildItem -Path 'frontend\\src' -Recurse -Include *.jsx,*.js
foreach \($f in $files\) {
    $c = Get-Content $f.FullName -Raw
    if \($c -match 'target="_blank"'\) {
        $c = $c -creplace ' target="_blank"', ''
        $c = $c -creplace 'target="_blank" ', ''
        $c = $c -creplace 'target="_blank"', ''
        Set-Content -Path $f.FullName -Value $c -NoNewline
        Write-Host "Removed target=_blank from: $\($f.Name\)"
    }
}
PSEOF)
